node -e "
const Database = require('better-sqlite3');
const db = new Database('/workspace/world.db');

// List tables
const tables = db.prepare(\"SELECT name FROM sqlite_master WHERE type='table'\").all();
console.log('Tables:', tables.map(t => t.name));

// Look for product tables
tables.forEach(t => {
  const info = db.prepare('PRAGMA table_info(' + t.name + ')').all();
  console.log('\nTable:', t.name);
  console.log('Columns:', info.map(c => c.name).join(', '));
});
"

node -e "
const Database = require('better-sqlite3');
const db = new Database('/workspace/world.db');

// Search for PROD-FA0948
const product = db.prepare(\"SELECT * FROM products WHERE product_id = 'PROD-FA0948'\").get();
console.log('=== PRODUCT: PROD-FA0948 ===');
console.log(JSON.stringify(product, null, 2));

// Get variants from rt_variants table
const variants = db.prepare(\"SELECT * FROM rt_variants WHERE product_id = 'PROD-FA0948'\").all();
console.log('\n=== VARIANTS (rt_variants table) ===');
console.log(JSON.stringify(variants, null, 2));

// Search for Aurora Smart Desk Lamp Pro
console.log('\n=== AURORA SMART DESK LAMP PRO (PROD-73FAB4) ===');
const aurora = db.prepare(\"SELECT * FROM products WHERE product_id = 'PROD-73FAB4'\").get();
console.log(JSON.stringify(aurora, null, 2));
"
